def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = []
    weak_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 100:
                    strong_prev.append(float(bid))
                else:
                    weak_prev.append(float(bid))

    if not alive:
        return float(min(budget, 8.0))

    slots = max(1, int(float(supply) / WATER_REQ))
    competitors = len(alive) + 1
    pressure = competitors - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = max(weak_prev) if weak_prev else 0.0
    strong_count = len(strong_prev)

    urgent = False
    if hp <= 3 or no_water_days >= 2:
        urgent = True
    elif hp <= 5 and no_water_days >= 1:
        urgent = True

    if urgent:
        if strong_count >= 1 and highest_prev >= 140:
            bid = 0.92 * DAILY_SALARY
        elif highest_prev > 0:
            bid = min(0.98 * DAILY_SALARY, highest_prev + 3.0)
        else:
            bid = 0.82 * DAILY_SALARY
        return float(max(0.0, min(budget, bid)))

    if slots >= competitors:
        bid = 6.0
    elif pressure <= 1:
        if moderate_prev > 0:
            bid = max(18.0, min(42.0, moderate_prev + 1.5))
        else:
            bid = 22.0
    else:
        if highest_prev >= 120:
            bid = 12.0 if hp >= 7 and no_water_days == 0 else 48.0
        elif highest_prev >= 80:
            bid = 26.0 if hp >= 7 else 52.0
        elif highest_prev >= 45:
            bid = min(60.0, highest_prev + 2.0)
        elif highest_prev > 0:
            bid = max(28.0, highest_prev + 2.0)
        else:
            bid = 30.0

    if day >= 8 and hp >= 7 and no_water_days == 0:
        bid *= 0.85
    if budget < DAILY_SALARY:
        bid = min(bid, max(8.0, budget * 0.7))

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['no_water_days'] >= 1:
        base_bid = DAILY_SALARY * 0.8
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.65

    my_bid = base_bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        effective_players = float(num_alive_opponents + 1)
        supply_per_player = current_supply / effective_players

        if supply_per_player < WATER_REQ:
            if highest_prev_bid >= DAILY_SALARY * 0.7:
                my_bid = max(my_bid, highest_prev_bid + (DAILY_SALARY * 0.05))
            else:
                my_bid = max(my_bid, avg_prev_bid * 1.1)
        else:
            if highest_prev_bid > my_bid:
                my_bid = max(my_bid, highest_prev_bid * 0.95)

    my_bid = max(my_bid, DAILY_SALARY * 0.3)

    my_bid = min(my_status['budget'], my_bid)

    return max(0.0, my_bid)
